#if UNITY_EDITOR
using System;
using System.IO;
using ProjectoRTS.Core;
using ProjectoRTS.UI;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.InputSystem.UI;
using UnityEngine.Rendering.Universal;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

namespace ProjectoRTS.EditorTools
{
    /// <summary>
    /// Creates the title screen once and registers it as build index 0.
    /// It only creates or overwrites TitleScreen.unity; the gameplay scene
    /// (Gameplay.unity) is never regenerated by this tool.
    /// </summary>
    public static class TitleScreenSetup
    {
        private const string TitleScenePath = "Assets/Scenes/TitleScreen.unity";
        private const string GameplayScenePath = "Assets/Scenes/Gameplay.unity";
        private const string LegacyGameplayScenePath = "Assets/Scenes/PlacementDemo.unity";
        private const string MusicAssetPath = "Assets/_Project/Audio/Musica_portada.mp3";
        private const string MusicSourcePath = "musica juego/Musica_portada.mp3";

        [MenuItem("ProjectoRTS/Setup/Create Title Screen")]
        public static void CreateTitleScreenFromMenu()
        {
            if (File.Exists(TitleScenePath))
            {
                bool overwrite = EditorUtility.DisplayDialog(
                    "Create Title Screen",
                    "TitleScreen.unity already exists. Recreate it?\n\nGameplay.unity and PlacementDemo.unity will not be modified.",
                    "Recreate",
                    "Cancel");

                if (!overwrite)
                {
                    return;
                }
            }

            if (!EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo())
            {
                return;
            }

            CreateTitleScreen(false);
        }

        public static void CreateTitleScreenBatch()
        {
            try
            {
                CreateTitleScreen(true);
                EditorApplication.Exit(0);
            }
            catch (Exception exception)
            {
                Debug.LogException(exception);
                EditorApplication.Exit(1);
            }
        }

        public static void ValidateTitleScreenBatch()
        {
            try
            {
                Scene scene = EditorSceneManager.OpenScene(TitleScenePath, OpenSceneMode.Single);

                TitleScreenController controller = UnityEngine.Object.FindFirstObjectByType<TitleScreenController>();
                Button button = UnityEngine.Object.FindFirstObjectByType<Button>();
                Canvas canvas = UnityEngine.Object.FindFirstObjectByType<Canvas>();
                EventSystem eventSystem = UnityEngine.Object.FindFirstObjectByType<EventSystem>();
                AudioSource music = UnityEngine.Object.FindFirstObjectByType<AudioSource>();
                AudioListener listener = UnityEngine.Object.FindFirstObjectByType<AudioListener>();

                SerializedObject serializedController = controller != null
                    ? new SerializedObject(controller)
                    : null;

                bool controllerReferencesValid = serializedController != null
                    && serializedController.FindProperty("playButton").objectReferenceValue == button
                    && serializedController.FindProperty("loadingOverlay").objectReferenceValue != null
                    && serializedController.FindProperty("loadingFill").objectReferenceValue != null
                    && serializedController.FindProperty("loadingLabel").objectReferenceValue != null
                    && serializedController.FindProperty("musicSource").objectReferenceValue == music
                    && serializedController.FindProperty("gameplaySceneName").stringValue == SceneFlow.GameplaySceneName;

                bool inputModuleValid = eventSystem != null
                    && eventSystem.GetComponent<InputSystemUIInputModule>() != null;

                EditorBuildSettingsScene[] scenes = EditorBuildSettings.scenes;
                bool buildSettingsValid = scenes.Length >= 2
                    && scenes[0].path == TitleScenePath
                    && scenes[0].enabled
                    && scenes[1].path == GameplayScenePath
                    && scenes[1].enabled;

                bool hasController = controller != null;
                bool hasButton = button != null;
                bool hasCanvas = canvas != null;
                bool hasEventSystem = eventSystem != null;
                bool hasMusic = music != null;
                bool hasClip = music != null && music.clip != null;
                bool musicLoops = music != null && music.loop;
                bool hasListener = listener != null;

                bool titleValid = hasController
                    && hasButton
                    && hasCanvas
                    && hasEventSystem
                    && inputModuleValid
                    && controllerReferencesValid
                    && hasMusic
                    && hasClip
                    && musicLoops
                    && hasListener;

                Scene gameplayScene = EditorSceneManager.OpenScene(GameplayScenePath, OpenSceneMode.Single);
                bool gameplayValid = gameplayScene.IsValid() && gameplayScene.rootCount > 0;
                bool valid = titleValid && buildSettingsValid && gameplayValid;

                Debug.Log(
                    $"[TitleScreenValidation] titleScene={scene.name} controller={hasController} " +
                    $"button={hasButton} canvas={hasCanvas} eventSystem={hasEventSystem} " +
                    $"inputModule={inputModuleValid} references={controllerReferencesValid} " +
                    $"music={hasMusic} clip={hasClip} loop={musicLoops} listener={hasListener} " +
                    $"buildSettings={buildSettingsValid} gameplayScene={gameplayScene.name} " +
                    $"gameplayRoots={gameplayScene.rootCount}");

                EditorApplication.Exit(valid ? 0 : 1);
            }
            catch (Exception exception)
            {
                Debug.LogException(exception);
                EditorApplication.Exit(1);
            }
        }

        private static void CreateTitleScreen(bool batchMode)
        {
            EnsureGameplayScene();
            EnsureMusicAsset();

            AudioClip musicClip = AssetDatabase.LoadAssetAtPath<AudioClip>(MusicAssetPath);
            if (musicClip == null)
            {
                throw new InvalidOperationException($"Could not load music clip at {MusicAssetPath}.");
            }

            Scene scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);

            CreateCamera();
            EventSystem eventSystem = CreateEventSystem();

            Button playButton = CreateCanvas(
                musicClip,
                eventSystem,
                out CanvasGroup loadingOverlay,
                out RectTransform loadingFill,
                out Text loadingLabel,
                out AudioSource musicSource);

            GameObject controllerObject = new GameObject("Title Screen Controller");
            TitleScreenController controller = controllerObject.AddComponent<TitleScreenController>();

            SerializedObject serializedController = new SerializedObject(controller);
            serializedController.FindProperty("playButton").objectReferenceValue = playButton;
            serializedController.FindProperty("loadingOverlay").objectReferenceValue = loadingOverlay;
            serializedController.FindProperty("loadingFill").objectReferenceValue = loadingFill;
            serializedController.FindProperty("loadingLabel").objectReferenceValue = loadingLabel;
            serializedController.FindProperty("gameplaySceneName").stringValue = SceneFlow.GameplaySceneName;
            serializedController.FindProperty("musicSource").objectReferenceValue = musicSource;
            serializedController.ApplyModifiedPropertiesWithoutUndo();

            EditorSceneManager.MarkSceneDirty(scene);
            EditorSceneManager.SaveScene(scene, TitleScenePath);
            ConfigureBuildSettings();

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();

            string mode = batchMode ? " (batch)" : string.Empty;
            Debug.Log($"[TitleScreenSetup] Created {TitleScenePath} and set it as build index 0{mode}.");
        }

        private static void EnsureGameplayScene()
        {
            if (AssetDatabase.LoadAssetAtPath<SceneAsset>(GameplayScenePath) != null)
            {
                return;
            }

            if (AssetDatabase.LoadAssetAtPath<SceneAsset>(LegacyGameplayScenePath) == null)
            {
                throw new FileNotFoundException(
                    $"Neither {GameplayScenePath} nor {LegacyGameplayScenePath} exists.");
            }

            AssetDatabase.CopyAsset(LegacyGameplayScenePath, GameplayScenePath);
            AssetDatabase.SaveAssets();
            Debug.Log($"[TitleScreenSetup] Copied {LegacyGameplayScenePath} to {GameplayScenePath}.");
        }

        private static void EnsureMusicAsset()
        {
            string projectRoot = Path.GetDirectoryName(Application.dataPath);
            string musicAssetFullPath = Path.Combine(projectRoot, MusicAssetPath);

            if (!File.Exists(musicAssetFullPath))
            {
                string musicSourceFullPath = Path.Combine(projectRoot, MusicSourcePath);

                if (!File.Exists(musicSourceFullPath))
                {
                    throw new FileNotFoundException(
                        $"Music source not found at {musicSourceFullPath}.");
                }

                Directory.CreateDirectory(Path.GetDirectoryName(musicAssetFullPath));
                File.Copy(musicSourceFullPath, musicAssetFullPath);
                AssetDatabase.ImportAsset(MusicAssetPath, ImportAssetOptions.ForceSynchronousImport);
            }

            AudioImporter importer = AssetImporter.GetAtPath(MusicAssetPath) as AudioImporter;
            if (importer == null)
            {
                throw new InvalidOperationException($"Could not get AudioImporter for {MusicAssetPath}.");
            }

            AudioImporterSampleSettings settings = importer.defaultSampleSettings;
            settings.loadType = AudioClipLoadType.Streaming;
            settings.compressionFormat = AudioCompressionFormat.Vorbis;
            settings.quality = 0.7f;
            settings.preloadAudioData = false;
            importer.defaultSampleSettings = settings;
            importer.SaveAndReimport();
        }

        private static void CreateCamera()
        {
            GameObject cameraObject = new GameObject(
                "Main Camera",
                typeof(Camera),
                typeof(AudioListener),
                typeof(UniversalAdditionalCameraData));

            cameraObject.tag = "MainCamera";
            cameraObject.transform.position = new Vector3(0f, 0f, -10f);

            Camera camera = cameraObject.GetComponent<Camera>();
            camera.clearFlags = CameraClearFlags.SolidColor;
            camera.backgroundColor = new Color(0.027f, 0.043f, 0.086f, 1f);
            camera.orthographic = true;
            camera.orthographicSize = 5f;
            camera.nearClipPlane = 0.1f;
            camera.farClipPlane = 100f;
        }

        private static EventSystem CreateEventSystem()
        {
            GameObject eventSystemObject = new GameObject(
                "EventSystem",
                typeof(EventSystem),
                typeof(InputSystemUIInputModule));

            EventSystem eventSystem = eventSystemObject.GetComponent<EventSystem>();
            eventSystemObject.GetComponent<InputSystemUIInputModule>().AssignDefaultActions();
            return eventSystem;
        }

        private static Button CreateCanvas(
            AudioClip musicClip,
            EventSystem eventSystem,
            out CanvasGroup loadingOverlay,
            out RectTransform loadingFill,
            out Text loadingLabel,
            out AudioSource musicSource)
        {
            GameObject canvasObject = new GameObject(
                "Title Canvas",
                typeof(RectTransform),
                typeof(Canvas),
                typeof(CanvasScaler),
                typeof(GraphicRaycaster));

            Canvas canvas = canvasObject.GetComponent<Canvas>();
            canvas.renderMode = RenderMode.ScreenSpaceOverlay;

            CanvasScaler scaler = canvasObject.GetComponent<CanvasScaler>();
            scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;
            scaler.referenceResolution = new Vector2(1920f, 1080f);
            scaler.screenMatchMode = CanvasScaler.ScreenMatchMode.MatchWidthOrHeight;
            scaler.matchWidthOrHeight = 0.5f;

            Font font = UnityEngine.Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
            if (font == null)
            {
                font = UnityEngine.Resources.GetBuiltinResource<Font>("Arial.ttf");
            }

            CreateBackground(canvasObject.transform);
            CreateTitle(canvasObject.transform, font);
            Button playButton = CreatePlayButton(canvasObject.transform, font);
            CreateVersionLabel(canvasObject.transform, font);
            loadingOverlay = CreateLoadingOverlay(canvasObject.transform, font, out loadingFill, out loadingLabel);

            GameObject musicObject = new GameObject("Music", typeof(AudioSource));
            musicSource = musicObject.GetComponent<AudioSource>();
            musicSource.clip = musicClip;
            musicSource.loop = true;
            musicSource.playOnAwake = true;
            musicSource.spatialBlend = 0f;
            musicSource.volume = 0.5f;

            eventSystem.firstSelectedGameObject = playButton.gameObject;
            return playButton;
        }

        private static void CreateBackground(Transform parent)
        {
            GameObject backgroundObject = new GameObject(
                "Background",
                typeof(RectTransform),
                typeof(Image));

            backgroundObject.transform.SetParent(parent, false);

            RectTransform rect = backgroundObject.GetComponent<RectTransform>();
            rect.anchorMin = Vector2.zero;
            rect.anchorMax = Vector2.one;
            rect.offsetMin = Vector2.zero;
            rect.offsetMax = Vector2.zero;

            Image image = backgroundObject.GetComponent<Image>();
            image.color = new Color(0.027f, 0.043f, 0.086f, 1f);
            image.raycastTarget = false;
        }

        private static void CreateTitle(Transform parent, Font font)
        {
            GameObject titleObject = new GameObject(
                "Title",
                typeof(RectTransform),
                typeof(Text),
                typeof(Shadow));

            titleObject.transform.SetParent(parent, false);

            RectTransform rect = titleObject.GetComponent<RectTransform>();
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.anchoredPosition = new Vector2(0f, 130f);
            rect.sizeDelta = new Vector2(1200f, 140f);

            Text text = titleObject.GetComponent<Text>();
            text.font = font;
            text.fontSize = 84;
            text.fontStyle = FontStyle.Bold;
            text.alignment = TextAnchor.MiddleCenter;
            text.color = Color.white;
            text.text = "PROYECTO RTS";
            text.raycastTarget = false;

            Shadow shadow = titleObject.GetComponent<Shadow>();
            shadow.effectColor = new Color(0f, 0f, 0f, 0.6f);
            shadow.effectDistance = new Vector2(0f, -4f);

            GameObject accentObject = new GameObject(
                "Accent",
                typeof(RectTransform),
                typeof(Image));

            accentObject.transform.SetParent(parent, false);

            RectTransform accentRect = accentObject.GetComponent<RectTransform>();
            accentRect.anchorMin = new Vector2(0.5f, 0.5f);
            accentRect.anchorMax = new Vector2(0.5f, 0.5f);
            accentRect.pivot = new Vector2(0.5f, 0.5f);
            accentRect.anchoredPosition = new Vector2(0f, 55f);
            accentRect.sizeDelta = new Vector2(220f, 4f);

            Image accent = accentObject.GetComponent<Image>();
            accent.color = new Color(0.78f, 0.62f, 0.28f, 1f);
            accent.raycastTarget = false;
        }

        private static Button CreatePlayButton(Transform parent, Font font)
        {
            GameObject buttonObject = new GameObject(
                "Play Button",
                typeof(RectTransform),
                typeof(Image),
                typeof(Button));

            buttonObject.transform.SetParent(parent, false);

            RectTransform rect = buttonObject.GetComponent<RectTransform>();
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.anchoredPosition = new Vector2(0f, -70f);
            rect.sizeDelta = new Vector2(360f, 84f);

            Image image = buttonObject.GetComponent<Image>();
            image.color = new Color(0.18f, 0.28f, 0.42f, 1f);

            Button button = buttonObject.GetComponent<Button>();
            button.targetGraphic = image;

            ColorBlock colors = button.colors;
            colors.normalColor = Color.white;
            colors.highlightedColor = new Color(0.85f, 0.9f, 1f);
            colors.pressedColor = new Color(0.65f, 0.75f, 0.9f);
            colors.selectedColor = Color.white;
            button.colors = colors;

            GameObject labelObject = new GameObject(
                "Label",
                typeof(RectTransform),
                typeof(Text),
                typeof(Shadow));

            labelObject.transform.SetParent(buttonObject.transform, false);

            RectTransform labelRect = labelObject.GetComponent<RectTransform>();
            labelRect.anchorMin = Vector2.zero;
            labelRect.anchorMax = Vector2.one;
            labelRect.offsetMin = Vector2.zero;
            labelRect.offsetMax = Vector2.zero;

            Text label = labelObject.GetComponent<Text>();
            label.font = font;
            label.fontSize = 30;
            label.fontStyle = FontStyle.Bold;
            label.alignment = TextAnchor.MiddleCenter;
            label.color = Color.white;
            label.text = "Jugar";
            label.raycastTarget = false;

            return button;
        }

        private static void CreateVersionLabel(Transform parent, Font font)
        {
            GameObject versionObject = new GameObject(
                "Version",
                typeof(RectTransform),
                typeof(Text));

            versionObject.transform.SetParent(parent, false);

            RectTransform rect = versionObject.GetComponent<RectTransform>();
            rect.anchorMin = Vector2.zero;
            rect.anchorMax = Vector2.zero;
            rect.pivot = Vector2.zero;
            rect.anchoredPosition = new Vector2(24f, 20f);
            rect.sizeDelta = new Vector2(300f, 30f);

            Text text = versionObject.GetComponent<Text>();
            text.font = font;
            text.fontSize = 16;
            text.alignment = TextAnchor.MiddleLeft;
            text.color = new Color(1f, 1f, 1f, 0.45f);
            text.text = $"v{Application.version}";
            text.raycastTarget = false;
        }

        private static CanvasGroup CreateLoadingOverlay(
            Transform parent,
            Font font,
            out RectTransform loadingFill,
            out Text loadingLabel)
        {
            GameObject overlayObject = new GameObject(
                "Loading Overlay",
                typeof(RectTransform),
                typeof(Image),
                typeof(CanvasGroup));

            overlayObject.transform.SetParent(parent, false);

            RectTransform overlayRect = overlayObject.GetComponent<RectTransform>();
            overlayRect.anchorMin = Vector2.zero;
            overlayRect.anchorMax = Vector2.one;
            overlayRect.offsetMin = Vector2.zero;
            overlayRect.offsetMax = Vector2.zero;

            Image overlayImage = overlayObject.GetComponent<Image>();
            overlayImage.color = new Color(0.015f, 0.02f, 0.04f, 0.98f);

            CanvasGroup group = overlayObject.GetComponent<CanvasGroup>();
            group.alpha = 0f;
            group.interactable = false;
            group.blocksRaycasts = false;

            GameObject labelObject = new GameObject(
                "Loading Label",
                typeof(RectTransform),
                typeof(Text));

            labelObject.transform.SetParent(overlayObject.transform, false);

            RectTransform labelRect = labelObject.GetComponent<RectTransform>();
            labelRect.anchorMin = new Vector2(0.5f, 0.5f);
            labelRect.anchorMax = new Vector2(0.5f, 0.5f);
            labelRect.pivot = new Vector2(0.5f, 0.5f);
            labelRect.anchoredPosition = new Vector2(0f, 40f);
            labelRect.sizeDelta = new Vector2(800f, 60f);

            loadingLabel = labelObject.GetComponent<Text>();
            loadingLabel.font = font;
            loadingLabel.fontSize = 32;
            loadingLabel.fontStyle = FontStyle.Bold;
            loadingLabel.alignment = TextAnchor.MiddleCenter;
            loadingLabel.color = Color.white;
            loadingLabel.text = "Cargando... 0%";
            loadingLabel.raycastTarget = false;

            GameObject barObject = new GameObject(
                "Progress Bar",
                typeof(RectTransform),
                typeof(Image));

            barObject.transform.SetParent(overlayObject.transform, false);

            RectTransform barRect = barObject.GetComponent<RectTransform>();
            barRect.anchorMin = new Vector2(0.5f, 0.5f);
            barRect.anchorMax = new Vector2(0.5f, 0.5f);
            barRect.pivot = new Vector2(0.5f, 0.5f);
            barRect.anchoredPosition = new Vector2(0f, -20f);
            barRect.sizeDelta = new Vector2(520f, 14f);

            Image barImage = barObject.GetComponent<Image>();
            barImage.color = new Color(1f, 1f, 1f, 0.12f);

            GameObject fillObject = new GameObject(
                "Fill",
                typeof(RectTransform),
                typeof(Image));

            fillObject.transform.SetParent(barObject.transform, false);

            loadingFill = fillObject.GetComponent<RectTransform>();
            loadingFill.anchorMin = Vector2.zero;
            loadingFill.anchorMax = new Vector2(0f, 1f);
            loadingFill.offsetMin = Vector2.zero;
            loadingFill.offsetMax = Vector2.zero;

            Image fillImage = fillObject.GetComponent<Image>();
            fillImage.color = new Color(0.28f, 0.48f, 0.72f, 1f);

            return group;
        }

        private static void ConfigureBuildSettings()
        {
            EditorBuildSettings.scenes = new[]
            {
                new EditorBuildSettingsScene(TitleScenePath, true),
                new EditorBuildSettingsScene(GameplayScenePath, true)
            };
        }
    }
}
#endif
